def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in grid[0] if v != 0)
    bh = next(i for i in range(1,h) if all(v == sep for v in grid[i]))
    bw = next(i for i in range(1,w) if grid[0][i] == sep)
    # The example shape is the nonzero pattern in a panel other than the marker panel.
    shape = None
    for br in range(0,h,bh+1):
        for c0 in range(0,w,bw+1):
            panel = [[grid[br+r][c0+c] for c in range(bw)] for r in range(bh)]
            if any(v not in (0,sep) for row in panel for v in row):
                shape = [[v not in (0,sep) for v in row] for row in panel]
                break
        if shape is not None: break
    out = [row[:] for row in grid]
    for br in range(0,h,bh+1):
        marker = next((v for r in range(bh) for v in grid[br+r][:bw] if v not in (0,sep)), 0)
        if not marker: continue
        for c0 in range(0,w,bw+1):
            for r in range(bh):
                for c in range(bw): out[br+r][c0+c] = marker if shape[r][c] else 0
    return out
